add_filter( 'woocommerce_product_add_to_cart_text', 'perfectpixel_label_if_in_cart', 40, 2 );

function perfectpixel_label_if_in_cart( $text, $product ) {
	if ( ! $product || ! function_exists( 'WC' ) || ! WC()->cart || ! $product->is_purchasable() || ! $product->is_in_stock() ) {
		return $text;
	}
	// In loops, only simple products have a real add to cart button.
	if ( 'woocommerce_product_add_to_cart_text' === current_filter() && ! $product->is_type( 'simple' ) ) {
		return $text;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] === (int) $product->get_id() ) {
			return '{{in_cart_label}}';
		}
	}
	return $text;
}
